// Deprecated C++ Storage Class Specifier (C++11)
// Removed entirely in C++17 (Annex D.2)

void legacy_loop(int limit) {
    // Original intent: Hint compiler to store 'i' in a CPU register
    register int i = 0;

    for (i = 0; i < limit; ++i) {
        // ... access 'i' frequently
    }
}

// Key Constraint:
// Cannot take the address of a register variable:
// register int x;
// int* ptr = &x; // ERROR

// Modern compilers (GCC, Clang) ignore the hint;
// optimization handled automatically via internal heuristics.
